    private void jButtonGravarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButtonGravarActionPerformed
        if (jTextFieldNome.getText().trim().isEmpty()) {
            JOptionPane.showMessageDialog(rootPane, "Informe o nome do local");
        return;
        }

        Local lc = new Local();

        lc.setNomeLocal(jTextFieldNome.getText());
        lc.setEndereco(jTextFieldEndereco.getText());
        lc.setNomeResponsavel(jTextFieldResponsavel.getText());
        lc.setCelularResponsavel(jTextFieldCelular.getText());
        lc.setEmailResponsavel(jTextFieldEmail.getText());

        LocalDao dao = new LocalDao();

        if (dao.inserir(lc) != null) {
            JOptionPane.showMessageDialog(rootPane, "Local cadastrado com sucesso");
            }
    }//GEN-LAST:event_jButtonGravarActionPerformed

